120	/**
121	 * Creates one runtime query function and its subscription API.
122	 *
123	 * Queries share the same validation contract as commands, but may also run preload logic and emit
124	 * reactive updates when subscribed to.
125	 */
126	function createQuery<TState>(
127	  serviceId: string,
128	  name: string,
129	  queryDef: RuntimeQueryDefinition<TState>,
130	  selfRef: WritableSelf<TState>,
131	  loadStaticState?: StaticStateLoader
132	): Query<unknown, unknown> {
133	  const createQueryCtx = (): QueryCtx<TState> => ({ self: selfRef });
134	
135	  /** Runs the query handler and validates the resolved output value. */
136	  const runHandler = async (input: unknown): Promise<unknown> => {
137	    const output = await queryDef.handler(input, createQueryCtx());
138	
139	    return validateSchema(queryDef.output, output, {
140	      kind: 'query',
141	      serviceId,
142	      name,
143	      phase: 'output',
144	    });
145	  };
146	
147	  /** Runs either static-store preloading or the query's own preload hook before execution. */
