 * Server-side registry for the open-service system.
 *
 * The runtime in [service-runtime.ts](./service-runtime.ts) knows how to turn a single service
 * definition into a callable instance. This module layers a process-global registry on top of that
 * so multiple services can register themselves, discover one another, and be described or
 * statically snapshotted as a group.
 *
 * It is intentionally server-only: it touches the filesystem when writing static snapshots and is
 * not meant to be bundled into the browser preview or manager.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

import { toMerged } from 'es-toolkit/object';

import {
  OpenServiceDuplicateRegistrationError,
  OpenServiceNotFoundError,
  OpenServiceUnsafeStaticPathError,
} from '../../server-errors.ts';
import { createService } from './service-runtime.ts';
import { buildStaticFiles as buildStaticStore } from './static-build.ts';
import type {
  AnyCommandDefinition,
  AnyQueryDefinition,
  Commands,
  Queries,
  ServiceDefinition,
  ServiceInstance,
  StaticStore,
} from './types.ts';

/** Type-erased service definition as stored in the global registry. */
type RegisteredDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
/** Type-erased runtime instance as stored in the global registry. */
type RegisteredInstance = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;

/** One registry slot pairs a resolved definition with the instance created from it. */
type RegistryEntry = {
  definition: RegisteredDefinition;
  instance: RegisteredInstance;
};

/**
 * Optional handler implementations supplied at registration time.
 *
 * Each entry replaces the `handler` of the query or command with the matching name while keeping
 * that operation's declared input/output schemas. Names that do not exist on the definition are
 * ignored so a definition never ends up with a schema-less operation.
 */
export type ServiceHandlerOverrides = {
  queries?: Record<string, AnyQueryDefinition<unknown>['handler']>;
  commands?: Record<string, AnyCommandDefinition<unknown>['handler']>;
};

/** Lightweight summary returned by `listServices()`. */
export type ServiceSummary = {
  id: string;
  description?: string;
  queryNames: string[];
  commandNames: string[];
};

/** Per-operation descriptor returned inside `describeService()`. */
export type OperationDescriptor = {
  name: string;
  description?: string;
};

/** Detailed descriptor returned by `describeService()`. */
export type ServiceDescriptor = {
  id: string;
  description?: string;
  queries: OperationDescriptor[];
  commands: OperationDescriptor[];
};

/** Options accepted by `writeOpenServiceStaticFiles()`. */
export type WriteOpenServiceStaticFilesOptions = {
  outputDir: string;
};

/**
 * The process-global service registry.
 *
 * It is keyed by service id so lookups, discovery, and static builds can operate on every service
 * that has registered itself in the current process.
 */
const registry = new Map<string, RegistryEntry>();

/**
 * Returns a copy of a definition with the provided handler implementations applied.
 *
 * The original definition object is never mutated; only operations that already exist are updated.
 */
function applyHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  handlers?: ServiceHandlerOverrides
): ServiceDefinition<TState, TQueries, TCommands> {
  if (!handlers?.queries && !handlers?.commands) {
    return definition;
  }

  const queries = { ...definition.queries } as Record<string, AnyQueryDefinition<TState>>;
  for (const [name, handler] of Object.entries(handlers.queries ?? {})) {
    if (queries[name]) {
      queries[name] = { ...queries[name], handler };
    }
  }

  const commands = { ...definition.commands } as Record<string, AnyCommandDefinition<TState>>;
  for (const [name, handler] of Object.entries(handlers.commands ?? {})) {
    if (commands[name]) {
      commands[name] = { ...commands[name], handler };
    }
  }

  return {
    ...definition,
    queries: queries as TQueries,
    commands: commands as TCommands,
  };
}

/**
 * Registers a service in the global registry and returns its runtime instance.
 *
 * Optional handler implementations are merged onto the definition before the instance is built. A
 * duplicate id is treated as a programming error and rejected loudly.
 */
export function registerService<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  handlers?: ServiceHandlerOverrides
): ServiceInstance<TState, TQueries, TCommands> {
  if (registry.has(definition.id)) {
    throw new OpenServiceDuplicateRegistrationError({ serviceId: definition.id });
  }

  const resolvedDefinition = applyHandlerOverrides(definition, handlers);
  const instance = createService(resolvedDefinition);

  registry.set(definition.id, {
    definition: resolvedDefinition as RegisteredDefinition,
    instance: instance as RegisteredInstance,
  });

  return instance;
}

/**
 * Resolves a registered service by its id.
 *
 * Returns the exact instance produced by `registerService()`. Rejects when no service with that id
 * has been registered.
 */
export async function getService<
  TState = unknown,
  TQueries extends Queries<TState> = Queries<TState>,
  TCommands extends Commands<TState> = Commands<TState>,
>(serviceId: string): Promise<ServiceInstance<TState, TQueries, TCommands>> {
  const entry = registry.get(serviceId);

  if (!entry) {
    throw new OpenServiceNotFoundError({ serviceId });
  }

  return entry.instance as ServiceInstance<TState, TQueries, TCommands>;
}

/** Returns every registered service instance synchronously, in registration order. */
export function getRegisteredServices(): RegisteredInstance[] {
  return Array.from(registry.values(), (entry) => entry.instance);
}

/** Returns a summary of every registered service. */
export async function listServices(): Promise<ServiceSummary[]> {
  return Array.from(registry.values(), ({ definition }) => ({
    id: definition.id,
    description: definition.description,
    queryNames: Object.keys(definition.queries),
    commandNames: Object.keys(definition.commands),
  }));
}

/**
 * Returns a detailed descriptor for one registered service.
 *
 * Rejects when no service with the given id has been registered.
 */
export async function describeService(serviceId: string): Promise<ServiceDescriptor> {
  const entry = registry.get(serviceId);

  if (!entry) {
    throw new OpenServiceNotFoundError({ serviceId });
  }

  const { definition } = entry;

  return {
    id: definition.id,
    description: definition.description,
    queries: Object.entries(definition.queries).map(([name, query]) => ({
      name,
      description: query.description,
    })),
    commands: Object.entries(definition.commands).map(([name, command]) => ({
      name,
      description: command.description,
    })),
  };
}

/** Removes every service from the global registry. Primarily used for test isolation. */
export function clearRegistry(): void {
  registry.clear();
}

